function searchAll(searchText,searchIn,movies){if(searchText.length){switch(searchIn){case"Title":movies=movies.filter(movie=>~movie.original_title.toUpperCase().indexOf(searchText.toUpperCase()));break;case"Actor":{movies=movies.filter(movie=>movie.actors.filter(actor=>!!actor&&~actor.toUpperCase().indexOf(searchText.toUpperCase())).length>0);break;}
case"Director":{movies=movies.filter(movie=>movie.director.filter(director=>!!director&&~director.toUpperCase().indexOf(searchText.toUpperCase())).length>0);break;}}}else if(movies.length!=allMovies.length){movies=[...allMovies];}
return movies;}
function sort(movs,sortBy){sortBy=sortBy||"year_of_release";if(sortBy=="original_title"){movs.sort((a,b)=>a[sortBy].localeCompare(b[sortBy]));}else{movs.sort((a,b)=>(a[sortBy]-b[sortBy])||(a["year_of_release"]-b["year_of_release"]));}
if(sortBy==="imdb_rating")
movs.sort((a,b)=>(b[sortBy]-a[sortBy])||!(b["year_of_release"]-a["year_of_release"]));return movs;}
var searchInField="Title";function searchIn(item){document.getElementById("searchIn").innerHTML=item.innerHTML;searchInField=item.innerHTML;document.getElementsByName("keyword")[0].placeholder="Search "+item.innerHTML.toLowerCase()+"s";}
window.openYT=openYT;function init(){createPagination(pages.length);document.querySelectorAll('.tooltipstered').forEach(e=>tooltip($(e)));}
let pageSize=32;let pages=paginate(allMovies,pageSize);var firstPageLoad=true;init();$(document)
